do $do$
declare run_id bigint; cid bigint;
begin
select id into cid from public.companies where ticker=$q$MSFT$q$;
if cid is null then raise exception 'company % not found', $q$MSFT$q$; end if;
if (select markets[1] from public.companies where id=cid) is distinct from 'US' then raise exception 'company % is not US-primary; refusing to write market data looked up by %', $q$MSFT$q$, $q$MSFT$q$; end if;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,started_at,finished_at,status,review_status) values ('market_data','batch',$q$MSFT Finnhub metric, recommendation trends, earnings calendar (M17)$q$,'none (Finnhub API, no model call)',0,0,0,$q$2026-10-29T03:21:35.234624+00:00$q$::timestamptz,$q$2026-10-29T03:21:40.009345+00:00$q$::timestamptz,$q$completed$q$,'unreviewed') returning id into run_id;
insert into public.company_metrics(company_id,as_of,data_period,pe_ttm,ev_ebitda,gross_margin,operating_margin,net_margin,revenue_growth_yoy,debt_to_equity,rec_period,rec_strong_buy,rec_buy,rec_hold,rec_sell,rec_strong_sell,source,fetched_at,status,run_id,note) values (cid,$q$2026-10-29$q$::date,$q$2026-06-30$q$::date,29.5088,20.831,67.94,46.73,40.31,17.79,0.2416,$q$2026-10-01$q$::date,22,40,3,0,0,'finnhub',$q$2026-10-29T03:21:40.009345+00:00$q$::timestamptz,'staged',run_id,null) on conflict (company_id,as_of,source) do update set data_period=excluded.data_period,pe_ttm=excluded.pe_ttm,ev_ebitda=excluded.ev_ebitda,gross_margin=excluded.gross_margin,operating_margin=excluded.operating_margin,net_margin=excluded.net_margin,revenue_growth_yoy=excluded.revenue_growth_yoy,debt_to_equity=excluded.debt_to_equity,rec_period=excluded.rec_period,rec_strong_buy=excluded.rec_strong_buy,rec_buy=excluded.rec_buy,rec_hold=excluded.rec_hold,rec_sell=excluded.rec_sell,rec_strong_sell=excluded.rec_strong_sell,fetched_at=excluded.fetched_at,run_id=excluded.run_id,note=excluded.note where public.company_metrics.status='staged';
delete from public.company_events where company_id=cid and source='finnhub' and status='staged' and event_date>=$q$2026-10-29$q$::date and event_date not in ($q$2027-01-26$q$::date);
insert into public.company_events(company_id,event_date,event_type,detail,source,fetched_at,status,run_id) values (cid,$q$2027-01-26$q$::date,'earnings',$q$Q2 2027$q$,'finnhub',$q$2026-10-29T03:21:40.009345+00:00$q$::timestamptz,'staged',run_id) on conflict (company_id,event_date,event_type,source) where status='staged' do update set detail=excluded.detail,fetched_at=excluded.fetched_at,run_id=excluded.run_id;
end $do$;
